CREATE FUNCTION get_customer_total(cust_id INT)
RETURNS NUMERIC AS $$
DECLARE
  total NUMERIC;
BEGIN
  SELECT SUM(amount) INTO total FROM orders WHERE customer_id = cust_id;
  RETURN total;
END;
$$ LANGUAGE plpgsql;
